//          code base (`A, B = 3, // note`, /* comments */, `typedef enum {` / `} name;`) as well as the native format.
export function formatDecls(text: string) {
  const src = text || ''
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
  // Changes: C enum mode only for real enum text (`enum`, or a line starting `NAME,` / `NAME = 3,`) – punctuation
  //          terminals ( { } , ; ) on their own lines and commas inside notes no longer switch to it.
  const isEnum = /\benum\b/.test(src) || /^\s*[A-Za-z_]\w*\s*(?:=[^,\n]*)?,/m.test(src)
  const items: { symbol: string; note: string }[] = []
  const comments: string[] = []

  if (isEnum) {
    const body = src
      .replace(/\/\*[\s\S]*?\*\//g, ' ')
      .replace(/\btypedef\b|\benum\b/g, ' ')
      .replace(/[A-Za-z_]\w*\s*\{/g, '{')
      .replace(/\}\s*[A-Za-z_]\w*\s*;?/g, '}')
      .replace(/[{};]/g, ',')
    for (const line of body.split('\n')) {
      const [code, ...rest] = line.split('//')
      const note = rest.join('//').trim()
      const parts = code.split(',').map((p) => p.replace(/=.*$/, '').trim())
      const symbols = parts.filter(Boolean).map((p) => p.split(/\s+/)[0])
      // A trailing `// note` belongs to the last enumerator on its line.
      symbols.forEach((symbol, i) => items.push({ symbol, note: i === symbols.length - 1 ? note : '' }))
    }
  } else {
    for (const line of src.split('\n')) {
      const trimmed = line.trim()
      if (trimmed.startsWith('#')) comments.push(trimmed)
      else items.push(...parseDecls(trimmed).map(({ symbol, note }) => ({ symbol, note: note.trim() })))
    }
  }

  const seen = new Map<string, { symbol: string; note: string }>()
  for (const it of items) {
    const prev = seen.get(it.symbol)
    if (!prev) seen.set(it.symbol, { ...it })
    else if (!prev.note && it.note) prev.note = it.note
  }
  const list = [...seen.values()].map((it) => ({ ...it, symbol: quote(it.symbol) }))
  const width = Math.max(0, ...list.filter((it) => it.note).map((it) => it.symbol.length))
  const lines = list.map((it) => (it.note ? `${it.symbol.padEnd(width)}  ${it.note}` : it.symbol))
  return [...comments, ...lines].join('\n') + (lines.length || comments.length ? '\n' : '')
}
